main {
    max-width: 900px;
    margin: 0 auto;
}

.image-preview {
    background-color: var(--color-bg);
    border-radius: var(--radius-lg);
    padding: 2rem;
    margin: 2rem;
    box-shadow: var(--shadow-md);
}

.image-container {
    margin-bottom: 2rem;
    text-align: center;
}

.preview-image {
    max-width: 100%;
    height: auto;
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-md);
    max-height: 400px;
}

.image-info {
    margin-bottom: 2rem;
}

.image-info h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    color: var(--color-text);
}

.image-details {
    color: var(--color-text-secondary);
    font-size: 0.875rem;
    margin-bottom: 0.5rem;
}

.image-description {
    color: var(--color-text-secondary);
    margin-bottom: 0;
}

/* Button Styles */
.image-actions {
    display: flex;
    gap: 1rem;
    justify-content: flex-start;
    flex-wrap: wrap;
}

.btn {
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 500;
    border: none;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: var(--transition);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    text-decoration: none;
