.delete-dialog[open] {
    animation: slideUp 0.3s ease-out;
}

@keyframes slideUp {
    from {
        transform: translateY(20px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

.dialog-content {
    padding: 2rem;
}

.delete-dialog h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 1rem;
    color: var(--color-text);
}

.dialog-message {
    color: var(--color-text-secondary);
    margin-bottom: 2rem;
    line-height: 1.5;
}

.dialog-actions {
    display: flex;
    gap: 1rem;
    justify-content: flex-end;
}

.dialog-actions .btn {
    min-width: 120px;
}

/* Responsive Design */
@media (max-width: 640px) {
    header h1 {
        font-size: 1.5rem;
    }

    .image-preview {
        padding: 1.5rem;
        margin: 1rem;
    }

    .image-actions {
        flex-direction: column;
    }

    .image-actions .btn {
        width: 100%;
    }

    .delete-dialog {
        width: 95%;
    }

    .dialog-actions {
        flex-direction: column-reverse;
    }

    .dialog-actions .btn {
        width: 100%;
    }

    .dialog-content {
        padding: 1.5rem;
    }

    .delete-dialog h2 {
        font-size: 1.25rem;
    }
}

/* High Contrast Mode Support */
@media (forced-colors: active) {
    .btn {
        border: 2px solid ButtonBorder;
    }

    .btn:focus-visible {
        outline: 2px solid ButtonText;
    }

    .delete-dialog {
        border: 2px solid CanvasText;
    }

    .preview-image {
        border: 1px solid CanvasText;
    }
}

